data class OcrResultPopupSettings(
    val widthDp: Int,
    val heightDp: Int,
    val contentScale: Float,
)

@Composable
fun OcrResultOverlay(
    onDismissRequest: () -> Unit,
    presentation: OcrResultPresentation,
    popupSettings: OcrResultPopupSettings,
    dimBackground: Boolean,
    queryText: String,
    initialSearchText: String = queryText,
    /**
     * Кто распознал: при ручном выборе областей качество сильно зависит от
     * движка, и без подписи непонятно, почему один и тот же фрагмент читается
     * то лучше, то хуже. null — источник неизвестен, подписи нет.
     */
    source: OcrTextSource? = null,
    anchorRect: RectF?,
    onCopyText: () -> Unit,
    searchState: DictionarySearchScreenModel.State,
    onQueryChange: (String) -> Unit,
    onSearch: (String) -> Unit,
    onTermGroupClick: (List<DictionaryTerm>) -> Unit,
    onPlayAudioClick: (List<DictionaryTerm>) -> Unit,
    onSpeak: () -> Unit = {},
    onChooseVoice: () -> Unit = {},
    onSpeakRole: (String) -> Unit = {},
    onAddToDictionary: () -> Unit = {},
    /**
     * Убрать распознанный текст со страницы, не закрывая карточку. Раньше
     * оверлей нельзя было убрать, не закрыв результат, — а на светлой
     * странице он всё равно мешал.
     */
    onHidePageOverlay: (() -> Unit)? = null,
) {
    BackHandler(onBack = onDismissRequest)
    // Словарей нет — не дёргаем поиск и не показываем «No Dictionaries
    // Enabled»: пользователю нужен сам распознанный текст.
    val noDictionaries = searchState.dictionaries.isEmpty()
    LaunchedEffect(queryText, initialSearchText, noDictionaries) {
        if (queryText.isNotBlank() && !noDictionaries) {
            onQueryChange(queryText)
            onSearch(initialSearchText)
        }
    }

    Box(modifier = Modifier.fillMaxSize()) {
        if (false) {
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .background(MaterialTheme.colorScheme.scrim.copy(alpha = 0.32f)),
            )
        }

        when {
            noDictionaries -> {
                OcrPlainTextCard(
                    text = queryText,
                    source = source,
                    onDismissRequest = onDismissRequest,
                    onCopyText = onCopyText,
                    onSpeak = onSpeak,
                    onChooseVoice = onChooseVoice,
                    onSpeakRole = onSpeakRole,
                    onAddToDictionary = onAddToDictionary,
                    onHidePageOverlay = onHidePageOverlay,
                )
            }
            presentation == OcrResultPresentation.POPUP && anchorRect != null -> {
                OcrResultPopup(
                    onDismissRequest = onDismissRequest,
                    anchorRect = anchorRect,
                    settings = popupSettings,
                    onCopyText = onCopyText,
                    searchState = searchState,
                    onQueryChange = onQueryChange,
                    onSearch = onSearch,
                    onTermGroupClick = onTermGroupClick,
                    onPlayAudioClick = onPlayAudioClick,
                )
            }
            else -> {
                OcrResultBottomSheet(
                    onDismissRequest = onDismissRequest,
                    onCopyText = onCopyText,
                    searchState = searchState,
                    onQueryChange = onQueryChange,
                    onSearch = onSearch,
                    onTermGroupClick = onTermGroupClick,
                    onPlayAudioClick = onPlayAudioClick,
                )
            }
        }
    }
}

/**
 * Карточка распознанного текста без словарной части: текст можно выделить
 * и скопировать, лишних сообщений «словари не найдены» нет.
 */
@Composable
private fun OcrPlainTextCard(
    text: String,
    source: OcrTextSource?,
    onDismissRequest: () -> Unit,
    onCopyText: () -> Unit,
    onSpeak: () -> Unit = {},
    onChooseVoice: () -> Unit = {},
    onSpeakRole: (String) -> Unit = {},
    onAddToDictionary: () -> Unit = {},
    onHidePageOverlay: (() -> Unit)? = null,
) {
    Box(
        modifier = Modifier.fillMaxSize(),
        contentAlignment = androidx.compose.ui.Alignment.BottomCenter,
    ) {
        androidx.compose.material3.Surface(
            shape = androidx.compose.foundation.shape.RoundedCornerShape(16.dp),
            color = MaterialTheme.colorScheme.surfaceContainerHigh,
            tonalElevation = 6.dp,
            modifier = Modifier
                .fillMaxWidth()
                .heightIn(max = 520.dp)
                .padding(24.dp),
        ) {
            androidx.compose.foundation.layout.Column(
                modifier = Modifier.padding(16.dp),
            ) {
                OcrEngineCaption(source)
                androidx.compose.material3.Text(
                    text = text,
                    style = MaterialTheme.typography.bodyLarge,
                    color = MaterialTheme.colorScheme.onSurface,
                    modifier = Modifier
                        .verticalScroll(androidx.compose.foundation.rememberScrollState())
                        .heightIn(max = 380.dp),
                )
                androidx.compose.foundation.layout.Spacer(
                    modifier = Modifier.height(12.dp),
                )
                androidx.compose.foundation.layout.Column {
                    androidx.compose.foundation.layout.Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = androidx.compose.foundation.layout.Arrangement.End,
                    ) {
                        androidx.compose.material3.TextButton(onClick = onSpeak) {
                            androidx.compose.material3.Text("▶ Голос")
                        }
                        androidx.compose.material3.TextButton(onClick = { onSpeakRole("female") }) {
                            androidx.compose.material3.Text("♀")
                        }
                        androidx.compose.material3.TextButton(onClick = { onSpeakRole("male") }) {
                            androidx.compose.material3.Text("♂")
                        }
                        androidx.compose.material3.TextButton(onClick = { onSpeakRole("narrator") }) {
                            androidx.compose.material3.Text("🎙")
                        }
                        androidx.compose.material3.TextButton(onClick = onChooseVoice) {
                            androidx.compose.material3.Text("Выбрать")
                        }
                    }
                    androidx.compose.foundation.layout.Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = androidx.compose.foundation.layout.Arrangement.End,
                    ) {
                        if (onHidePageOverlay != null) {
                            androidx.compose.material3.TextButton(onClick = onHidePageOverlay) {
                                androidx.compose.material3.Text("👁 Скрыть текст")
                            }
                        }
                        androidx.compose.material3.TextButton(onClick = onCopyText) {
                            androidx.compose.material3.Text("Копировать")
                        }
                        androidx.compose.material3.TextButton(onClick = onAddToDictionary) {
                            androidx.compose.material3.Text("＋ Словарь")
                        }
                        androidx.compose.material3.TextButton(onClick = onDismissRequest) {
                            androidx.compose.material3.Text("Закрыть")
                        }
                    }
                }
            }
        }
    }
}

/**
 * Подпись «кто распознал» над распознанным текстом.
 *
