             style = MaterialTheme.typography.bodySmall,
             color = MaterialTheme.colorScheme.onSurfaceVariant,
             modifier = Modifier.weight(1f).padding(horizontal = 16.dp, vertical = 4.dp),
         )
         IconButton(
             onClick = {
                 reloadKey++
                 context.toast("Обновляю список приложений")
