         is InstalledApps.AppsState.Ready -> {
             if (state.entries.isEmpty()) {
                 Text(
                     text = "Запускаемых приложений не найдено",
                     style = MaterialTheme.typography.bodyMedium,
                     modifier = Modifier.padding(16.dp),
