/**
 * Просит у системы разрешение на захват экрана.
 *
 * Android не даёт начать захват из фонового сервиса: нужен
 * [android.media.projection.MediaProjectionManager] и результат,
 * возвращённый в [android.app.Activity]. Поэтому просить разрешение
 * может только видимая activity — шлём запрос и ждём.
 */
private fun requestCapture() {
    val fixed = fixedRegionRect()
    if (fixed == null) {
        toast("Сначала выдели область рамки кнопкой ✏")
        return
    }
    runCatching {
        val mpm = getSystemService(Context.MEDIA_PROJECTION_SERVICE)
            as android.media.projection.MediaProjectionManager
        val intent = mpm.createScreenCaptureIntent()
        intent.putExtra(
            android.media.projection.MediaProjection.EXTRA_MEDIA_FRAME,
            Rect(fixed),
        )
        startActivityForResult(intent, REQUEST_CAPTURE)
    }.onFailure {
        toast("Захват экрана недоступен")
    }
}

@Deprecated("Deprecated in Java")
override fun onActivityResult(requestCode: Int, resultCode: Int, data: Intent?) {
    @Suppress("DEPRECATION")
    super.onActivityResult(requestCode, resultCode, data)
    if (requestCode != REQUEST_CAPTURE) return
    if (resultCode != android.app.Activity.RESULT_OK || data == null) {
        toast("Захват экрана не разрешён")
        return
    }
    val projection = runCatching {
        val mpm = getSystemService(Context.MEDIA_PROJECTION_SERVICE)
            as android.media.projection.MediaProjectionManager
        mpm.getMediaProjection(resultCode, data)
    }.getOrNull()
    if (projection == null) {
        toast("Не удалось начать захват экрана")
        return
    }
    startReading(projection)
}

private fun dp(v: Float): Int = (v * resources.displayMetrics.density).toInt().coerceAtLeast(1)

