/**
 * Вкладка «AI»: один слой — токен и запуск. После запуска в этой же вкладке
 * открывается сайт-хаб npm-hub (дашборд / терминал / файлы / git / инструменты)
 * с GitHub-ранера, где живут CLI-агенты. Агент НЕ форсится при запуске —
 * пользователь сам выбирает и устанавливает его внутри хаба (как в оригинале).
 */
data object AiChatTab : Tab {

    override val options: TabOptions
        @Composable
        get() = TabOptions(
            index = 9u,
            title = "AI",
            icon = rememberVectorPainter(Icons.Outlined.SmartToy),
        )

    // Запуск переживает уход со вкладки и сворачивание приложения
    private val chatScope = kotlinx.coroutines.CoroutineScope(
        kotlinx.coroutines.SupervisorJob() + Dispatchers.IO,
    )
    private val hubStatusFlow = MutableStateFlow("")
    private val hubStartingFlow = MutableStateFlow(false)
    // Fix 5: активная сессия живёт на уровне ОБЪЕКТА, а не в remember —
    // при переключении вкладки (и обратно) WebView не «теряется».
    private val hubSessionFlow = MutableStateFlow<RunnerLlm.Session?>(null)

    private fun rememberSession(s: RunnerLlm.Session) {
        hubSessionFlow.value = s
    }

    @Composable
    override fun Content() {
        val context = LocalContext.current
        val prefs = remember { Injekt.get<OcrPreferences>() }
        val pat by prefs.githubPat().changes().collectAsState(initial = prefs.githubPat().get())
        val starting by hubStartingFlow.collectAsState()
        val status by hubStatusFlow.collectAsState()
        val session by hubSessionFlow.collectAsState()
        var sessions by remember {
            mutableStateOf(runCatching { RunnerLlm.listSessions(context) }.getOrDefault(emptyList()))
        }
        // Лента событий ранера: последние прогоны и пошаговая лента задач.
        // Читатель просил видеть, что ранер делал, не выспрашивая агента.
        var events by remember { mutableStateOf<List<AiGithub.Run>>(emptyList()) }
        var eventsLoading by remember { mutableStateOf(false) }
        var eventsError by remember { mutableStateOf("") }

        val loadEvents: () -> Unit = {
            if (pat.isBlank()) {
                eventsError = "Сначала вставьте GitHub PAT"
            } else {
                eventsLoading = true
                eventsError = ""
                val token = pat.trim()
                chatScope.launch {
                    val got = runCatching { AiGithub.runs(token, AiGithub.DEFAULT_REPO, perPage = 8) }
                        .getOrElse { emptyList() }
                    withContext(Dispatchers.Main) {
                        events = got
                        eventsLoading = false
                        if (got.isEmpty() && eventsError.isBlank()) {
                            eventsError = "Прогонов не найдено или сеть недоступна"
                        }
                    }
                }
            }
        }

        val openSession = session
        if (openSession != null) {
            HubWebView(
                session = openSession,
                onClose = { hubSessionFlow.value = null },
            )
        } else {
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .statusBarsPadding()
                    .imePadding()
                    .verticalScroll(rememberScrollState())
                    .padding(16.dp),
                verticalArrangement = Arrangement.spacedBy(12.dp),
            ) {
                Text("OpenCode-агент", style = MaterialTheme.typography.titleMedium)
                Text(
                    "Запускает сайт-хаб (npm-hub) на GitHub-ранере: дашборд, терминал, " +
                        "файлы, git, инструменты. Нужного CLI-агента (opencode, DeepSeek, UTIM, " +
                        "AI Shell и др.) вы сами выбираете и устанавливаете прямо внутри хаба. " +
                        "Ранер работает вашим PAT аккаунта, поэтому видит и меняет ВСЕ репозитории " +
                        "аккаунта. Нужен PAT с правом actions:write.",
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                )
                OutlinedTextField(
                    value = pat,
                    onValueChange = { token ->
                        // Пробелы по краям ломают GitHub Auth: token = " ghp_…x "
                    // считается невалидным и старт сессии падает с 401.
                        prefs.githubPat().set(token.trim())
                    },
                    label = { Text("GitHub PAT") },
                    modifier = Modifier.fillMaxWidth(),
                    maxLines = 1,
                )
                var elapsed by remember { mutableStateOf(0L) }
                LaunchedEffect(starting) {
                    elapsed = 0
                    while (starting) {
                        delay(1000)
                        elapsed++
                    }
                }
                FilledTonalButton(
                    enabled = !starting && pat.isNotBlank(),
                    onClick = {
                        val trimmed = pat.trim()
                        val looksLikePat = trimmed.startsWith("ghp_") ||
                            trimmed.startsWith("github_pat_") ||
                            trimmed.startsWith("gho_") ||
                            trimmed.startsWith("ghs_") ||
                            trimmed.startsWith("ghr_")
                        if (!looksLikePat) {
                            hubStatusFlow.value =
                                "❌ Токен не похож на GitHub PAT. Нужен токен, " +
                                "начинающийся на ghp_ / github_pat_ / gho_ (Settings → Developer settings → " +
                                "Personal access tokens). Вставлен Discord- или другой токен?"
                            return@FilledTonalButton
                        }
                        hubStartingFlow.value = true
                        hubStatusFlow.value = "⏳ Запуск хаба npm-hub…"
                        val appCtx = context.applicationContext
                        chatScope.launch {
                            val s = runCatching {
                                RunnerLlm.startOpenCode(
                                    appCtx,
                                    { st -> hubStatusFlow.value = st },
                                    os = "linux",
                                    ui = "mobile",
                                )
                            }.getOrElse {
                                hubStatusFlow.value = "❌ Ошибка запуска: ${it.message ?: it}"
                                null
                            }
                            withContext(Dispatchers.Main) {
                                hubStartingFlow.value = false
                                if (s != null) {
                                    sessions = runCatching { RunnerLlm.listSessions(context) }
                                        .getOrDefault(emptyList())
                                    rememberSession(s)
                                }
                            }
                        }
                    },
                ) { Text(if (starting) "Запускаем…" else "▶ Запустить") }
                if (status.isNotBlank()) {
                    Text(
                        if (starting) "$status • ${elapsed / 60}:${"%02d".format(elapsed % 60)}"
                        else status,
                        style = MaterialTheme.typography.bodySmall,
                    )
                }
                // Лента событий ранера. Раньше читатель видел только «сессии»
                // и кнопку «Открыть»: что ранер делал внутри прогона, не было
                // видно нигде, хотя GitHub Actions это знает.
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    FilterChip(
                        selected = events.isNotEmpty(),
                        onClick = { loadEvents() },
                        label = { Text("События ранера") },
                    )
                    if (eventsLoading) {
                        Text("Загрузка…", style = MaterialTheme.typography.labelSmall)
                    }
                }
                if (eventsError.isNotBlank()) {
                    Text(
                        eventsError,
                        style = MaterialTheme.typography.labelSmall,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                    )
                }
                events.forEach { r ->
                    var steps by remember(r.id) { mutableStateOf<String?>(null) }
                    var stepsLoading by remember(r.id) { mutableStateOf(false) }
                    Column(modifier = Modifier.fillMaxWidth().padding(vertical = 2.dp)) {
                        Text(
                            "#${r.id} ${r.name} — ${r.stateRu}",
                            style = MaterialTheme.typography.bodySmall,
                        )
                        Text(
                            "Показать шаги",
                            style = MaterialTheme.typography.labelSmall,
                            color = MaterialTheme.colorScheme.primary,
                            modifier = Modifier.clickable {
                                if (steps != null || stepsLoading) return@clickable
                                stepsLoading = true
                                val token = pat.trim()
                                val runId = r.id
                                chatScope.launch {
                                    val text = runCatching {
                                        AiGithub.renderJobs(AiGithub.jobs(token, runId))
                                    }.getOrElse { "Не удалось прочитать шаги: ${it.message}" }
                                    withContext(Dispatchers.Main) {
                                        steps = text
                                        stepsLoading = false
                                    }
                                }
                            },
                        )
                        if (stepsLoading) {
                            Text("…", style = MaterialTheme.typography.labelSmall)
                        }
                        steps?.let { txt ->
                            Text(
                                txt,
                                style = MaterialTheme.typography.labelSmall,
                                color = MaterialTheme.colorScheme.onSurfaceVariant,
                            )
                        }
                    }
                }
                if (sessions.isNotEmpty()) {
                    Text("Сессии:", style = MaterialTheme.typography.bodySmall)
                    sessions.forEach { s ->
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                        ) {
                            Text(
                                "${s.model} • ${s.messages.size} сообщ. • ${s.os}",
                                style = MaterialTheme.typography.bodySmall,
                                modifier = Modifier.weight(1f),
                            )
                            if (s.terminalUrl != null || s.url != null) {
                                FilterChip(
                                    selected = false,
                                    onClick = { rememberSession(s) },
                                    label = { Text("Открыть") },
                                )
                            }
                            FilterChip(
                                selected = false,
                                onClick = {
                                    runCatching {
                                        RunnerLlm.deleteSession(context, s)
                                        sessions = RunnerLlm.listSessions(context)
                                    }
                                },
                                label = { Text("✕") },
                            )
                        }
                    }
                }
            }
        }
    }

    /** Сайт-хаб npm-hub в той же вкладке: loading-экран вместо чёрного + ошибки. */
    @Composable
    @android.annotation.SuppressLint("SetJavaScriptEnabled")
    private fun HubWebView(
        session: RunnerLlm.Session,
        onClose: () -> Unit,
    ) {
        val context = LocalContext.current
        val url = session.terminalUrl ?: session.url.orEmpty()
        var loading by remember(session.id) { mutableStateOf(true) }
        var error by remember(session.id) { mutableStateOf<String?>(null) }
        val webView = remember(session.id, url) {
            runCatching {
                WebView(context).apply {
                    // На чёрном фоне «протухающий» туннель выглядел как мёртвый экран.
                    setBackgroundColor(android.graphics.Color.WHITE)
                    isFocusable = true
                    isFocusableInTouchMode = true
                    settings.javaScriptEnabled = true
                    settings.domStorageEnabled = true
                    settings.loadWithOverviewMode = false
                    settings.useWideViewPort = false
                    settings.builtInZoomControls = false
                    settings.displayZoomControls = false
                    settings.mixedContentMode = android.webkit.WebSettings.MIXED_CONTENT_ALWAYS_ALLOW
                    webViewClient = object : WebViewClient() {
                        override fun onReceivedHttpAuthRequest(
                            view: WebView?,
                            handler: HttpAuthHandler,
                            host: String?,
                            realm: String?,
                        ) {
                            runCatching { handler.proceed("yomikai", session.apiKey.orEmpty()) }
                        }

                        override fun onPageFinished(view: WebView?, url: String?) {
                            loading = false
                            error = null
                            view?.requestFocus()
                        }

                        override fun onReceivedError(
                            view: WebView?,
                            errorCode: Int,
                            description: String?,
                            failingUrl: String?,
                        ) {
                            loading = false
                            error = "Ошибка загрузки ($errorCode): $description"
                        }

                        override fun onReceivedHttpError(
                            view: WebView?,
                            request: android.webkit.WebResourceRequest?,
                            errorResponse: android.webkit.WebResourceResponse?,
                        ) {
                            loading = false
                            val code = errorResponse?.statusCode ?: 0
                            val mime = errorResponse?.mimeType.orEmpty()
                            // Discord api error format leaked through a proxy/token:
                            // {"success":false,"result":null,"errors":[{"code":10005,...}]}
                            val body = runCatching {
                                errorResponse?.data?.bufferedReader()?.use { it.readText() }.orEmpty()
                            }.getOrDefault("").take(300)
                            if (code == 405 || body.contains("method not allowed", ignoreCase = true)) {
                                error = "Ранер ответил $code (Method Not Allowed). Скорее всего в поле " +
                                    "GitHub PAT вставлен НЕ-GitHub токен (например Discord). Возьмите " +
                                    "настоящий GitHub PAT (ghp_/github_pat_). Ответ: $body"
                            } else {
                                error = "HTTP $code на сайте ранера" +
                                    body.takeIf { it.isNotBlank() }?.let { "\n$it" }.orEmpty()
                            }
                        }
                    }
                    if (url.isNotBlank()) loadUrl(url)
                }
            }.getOrElse {
                error = "WebView не создался: ${it.message ?: it}"
                null
            }
        }
        DisposableEffect(webView) {
            onDispose {
                runCatching {
                    (webView?.parent as? android.view.ViewGroup)?.removeView(webView)
                    webView?.stopLoading()
                    webView?.destroy()
                }
            }
        }

        Column(modifier = Modifier.fillMaxSize().statusBarsPadding()) {
            Row(
                modifier = Modifier.fillMaxWidth().padding(horizontal = 12.dp, vertical = 4.dp),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(8.dp),
            ) {
                Text(
                    "npm-hub • ${session.os}" +
                        (if (loading) " • подключение…" else " • сайт"),
                    style = MaterialTheme.typography.bodySmall,
                    modifier = Modifier.weight(1f),
                )
                IconButton(onClick = {
                    loading = true
                    error = null
                    runCatching { webView?.reload() }
                }) {
                    Icon(Icons.Outlined.Refresh, contentDescription = "Перезагрузить")
                }
                TextButton(onClick = onClose) { Text("Закрыть") }
            }
            if (webView != null && error == null) {
                AndroidView(
                    factory = { webView },
                    modifier = Modifier.fillMaxSize(),
                )
            } else {
                Column(
                    modifier = Modifier.fillMaxSize().padding(24.dp),
                    verticalArrangement = Arrangement.Center,
                    horizontalAlignment = Alignment.CenterHorizontally,
                ) {
                    Text(
                        error ?: "Сайт хаба недоступен. Проверьте, что ранер ещё жив.",
                        style = MaterialTheme.typography.bodyMedium,
                    )
                    FilledTonalButton(
                        onClick = { error = null; loading = true; runCatching { webView?.reload() } },
                    ) { Text("Попробовать снова") }
                    TextButton(onClick = onClose) { Text("Закрыть и к запуску") }
                }
            }
        }
    }
}

