/**
 * Настройки AI-ассистента: реестр бэкендов чата с их готовностью на этом
 * устройстве, состояние рабочей области и плагинов разработчика, плюс
 * доступ к самой вкладке «AI».
 *
 * Переключатели бэкенда, моделей и ключей намеренно НЕ дублируются: они живут
 * в настройках вкладки AI (⚙), и второй источник истины мгновенно разошёлся бы
 * с первым. Задача этого экрана — показать, что выбрано, готово ли оно и где
 * это менять.
 */
object SettingsAiScreen : SearchableSettings {

    @ReadOnlyComposable
    @Composable
    override fun getTitleRes() = MR.strings.pref_category_ai

    @Composable
    override fun getPreferences(): List<Preference> {
        val context = LocalContext.current
        val navigator = LocalNavigator.currentOrThrow
        val prefs = remember { Injekt.get<OcrPreferences>() }

        val online = rememberNetworkState(context)
        val backend by prefs.aiBackend().collectPreferenceAsState()
        val provider by prefs.aiProvider().collectPreferenceAsState()

        // Снимок состояния: настройки, установленные .task-модели, сессия ранера.
        // Сеть берём из общего наблюдателя, чтобы статус пересчитывался при её
        // пропаже без перечитывания всех настроек.
        val state = remember(online, prefs, context) {
            AiBackends.state(context, prefs).copy(networkAvailable = online)
        }
        val statuses = remember(state, provider) {
            AiBackends.ALL.associate { it.id to AiBackends.statusOf(it, state, provider) }
        }

        // Рабочая область и плагины разработчика — это файлы на диске, поэтому
        // считаем их один раз на вход в экран, а не на каждую рекомпозицию.
        val workspace = remember(context) {
            runCatching {
                AiPlugins.list(context).size to AiWorkspace.listAll(context).size
            }.getOrDefault(0 to 0)
        }

        // Свои провайдеры из реестра AiProviders (файлы в workspace/providers):
        // добавляются в список выбора провайдера в группе «Модели и ключи».
        val userProviders = remember(context) {
            eu.kanade.tachiyomi.data.ai.AiProviders.list(context)
        }

        return listOf(
            getBackendsGroup(statuses = statuses, selected = backend),
            getModelKeyGroup(prefs = prefs, userProviders = userProviders),
            getWorkspaceGroup(plugins = workspace.first, files = workspace.second),
            getAccessGroup(prefs = prefs, context = context, navigator = navigator),
        )
    }

    /**
     * «Модели и ключи»: провайдер, модель Zen, ключ и модель OpenRouter.
     * Пишет в те же преференсы (`aiProvider`, `zenModel`, `openrouterApiKey`,
     * `openrouterFreeModel`), что и настройки AI-чата и модель-пикер в читалке,
     * поэтому расхождений между экранами нет.
     */
    @Composable
    private fun getModelKeyGroup(
        prefs: OcrPreferences,
        userProviders: List<eu.kanade.tachiyomi.data.ai.AiProviders.Spec>,
    ): Preference.PreferenceGroup {
        val providerEntries = buildMap {
            put(eu.kanade.tachiyomi.data.ai.AiAssistant.PROVIDER_ZEN, "Zen (без ключа)")
            put(eu.kanade.tachiyomi.data.ai.AiAssistant.PROVIDER_OPENROUTER, "OpenRouter")
            // Свои провайдеры (id -> название) добавляются как обычный элемент
            // списка, потому что aiProvider хранит именно их id.
            userProviders.forEach { spec ->
                put(spec.id, spec.title.ifBlank { spec.id })
            }
        }
        return Preference.PreferenceGroup(
            title = "Модели и ключи",
            preferenceItems = listOf(
                Preference.PreferenceItem.ListPreference(
                    preference = prefs.aiProvider(),
                    entries = providerEntries,
                    title = "Провайдер",
                    subtitle = "Провайдер: %s",
                ),
                Preference.PreferenceItem.ListPreference(
                    preference = prefs.zenModel(),
                    entries = eu.kanade.tachiyomi.data.ai.AiAssistant.ZEN_MODELS.associateWith { it },
                    title = "Модель Zen",
                    subtitle = "Модель: %s",
                ),
                Preference.PreferenceItem.EditTextPreference(
                    preference = prefs.openrouterApiKey(),
                    title = "OpenRouter API-ключ",
                    subtitle = "Ключ: %s",
                ),
                Preference.PreferenceItem.EditTextPreference(
                    preference = prefs.openrouterFreeModel(),
                    title = "OpenRouter модель (:free)",
                    subtitle = "Модель: %s",
                ),
                Preference.PreferenceItem.InfoPreference(
                    title = "Без ключа работают бесплатные модели Zen. Для OpenRouter нужен ключ; модель можно выбрать из списка :free.",
                ),
            ),
        )
    }

    @Composable
    private fun getBackendsGroup(
        statuses: Map<String, AiBackendStatus>,
        selected: String,
    ): Preference.PreferenceGroup {
        val current = AiBackends.byId(selected)
        return Preference.PreferenceGroup(
            title = stringResource(MR.strings.pref_ai_backends_group),
            preferenceItems = AiBackends.ALL.map { plugin ->
                Preference.PreferenceItem.TextPreference(
                    title = backendTitle(
                        plugin = plugin,
                        isSelected = plugin.id == selected,
                        status = statuses[plugin.id],
                    ),
                    subtitle = backendSubtitle(plugin = plugin, status = statuses[plugin.id]),
                )
            } + listOf(
                Preference.PreferenceItem.InfoPreference(
                    title = stringResource(MR.strings.pref_ai_backend_current).format(current.title),
                ),
                Preference.PreferenceItem.InfoPreference(
                    title = stringResource(MR.strings.pref_ai_backend_switch_hint),
                ),
            ),
        )
    }

    @Composable
    private fun getWorkspaceGroup(plugins: Int, files: Int): Preference.PreferenceGroup =
        Preference.PreferenceGroup(
            title = stringResource(MR.strings.pref_ai_workspace_group),
            preferenceItems = listOf(
                Preference.PreferenceItem.InfoPreference(
                    title = stringResource(MR.strings.pref_ai_workspace_files).format(files),
                ),
                Preference.PreferenceItem.InfoPreference(
                    title = stringResource(MR.strings.pref_ai_workspace_plugins).format(plugins),
                ),
                Preference.PreferenceItem.InfoPreference(
                    title = stringResource(MR.strings.pref_ai_workspace_hint),
                ),
            ),
        )

    @Composable
    private fun getAccessGroup(
        prefs: OcrPreferences,
        context: Context,
        navigator: Navigator,
    ): Preference.PreferenceGroup =
        Preference.PreferenceGroup(
            title = stringResource(MR.strings.pref_ai_access_group),
            preferenceItems = listOf(
                Preference.PreferenceItem.TextPreference(
                    title = stringResource(MR.strings.pref_ai_open_chat),
                    subtitle = stringResource(MR.strings.pref_ai_open_chat_summary),
                    onClick = {
                        // Тот же приём, что у кнопки «настройки OCR» в читалке:
                        // вкладка AI живёт в нижней навигации, поэтому открываем
                        // её интентом с extra, а не навигатором настроек.
                        context.startActivity(
                            Intent(context, MainActivity::class.java)
                                .putExtra(MainActivity.EXTRA_OPEN_AI_CHAT, true),
                        )
                        navigator.pop()
                    },
                ),
                Preference.PreferenceItem.SwitchPreference(
                    preference = prefs.aiTabVisible(),
                    title = stringResource(MR.strings.pref_ai_tab_visible),
                    subtitle = stringResource(MR.strings.pref_ai_tab_visible_summary),
                ),
                Preference.PreferenceItem.SwitchPreference(
                    preference = prefs.aiHttpServer(),
                    title = stringResource(MR.strings.pref_ai_http_server),
                    subtitle = stringResource(MR.strings.pref_ai_http_server_summary),
                ),
            ),
        )

    @Composable
    private fun backendTitle(
        plugin: AiBackends.Plugin,
        isSelected: Boolean,
        status: AiBackendStatus?,
    ): String = buildString {
        append(plugin.title)
        append(" • ")
        append(
            when {
                isSelected -> stringResource(MR.strings.pref_ai_backend_selected)
                status?.available == true -> stringResource(MR.strings.pref_ai_backend_ready)
                else -> stringResource(MR.strings.pref_ai_backend_not_ready)
            },
        )
        if (plugin.offline) {
            append(" • ")
            append(stringResource(MR.strings.pref_ai_backend_offline))
        }
    }

    @Composable
    private fun backendSubtitle(
        plugin: AiBackends.Plugin,
        status: AiBackendStatus?,
    ): String = buildString {
        append(plugin.summary)
        if (status == null) return@buildString
        append('\n')
        append(status.detail)
        if (status.missing.isNotEmpty()) {
            // Подписи требований готовим до joinToString: внутри его лямбды
            // @Composable вызывать нельзя.
            val labels = status.missing.associateWith { requirementLabel(it) }
            append('\n')
            append(stringResource(MR.strings.pref_ai_requires))
            append(": ")
            append(status.missing.joinToString(", ") { labels.getValue(it) })
        }
    }

    @Composable
    private fun requirementLabel(requirement: AiRequirement): String =
        stringResource(
            when (requirement) {
                AiRequirement.NETWORK -> MR.strings.pref_ai_requires_network
                AiRequirement.OPENROUTER_KEY -> MR.strings.pref_ai_requires_openrouter_key
                AiRequirement.GITHUB_PAT -> MR.strings.pref_ai_requires_github_pat
                AiRequirement.RUNNER_ALLOWED -> MR.strings.pref_ai_requires_runner_allowed
                AiRequirement.MODEL_DOWNLOAD -> MR.strings.pref_ai_requires_model
                AiRequirement.RUNNER_SESSION -> MR.strings.pref_ai_requires_runner_session
            },
        )
}

/**
 * Значки 🔊 на рамках распознанных реплик в читалке. По умолчанию выключено,
 * чтобы не мешать чтению; включается переключателем в плавающем меню.
 */
fun voiceIcons() = preferenceStore.getBoolean("pref_autoread_voice_icons", false)

/**
 * Автоматически начинать чтение (скан + озвучка) при открытии главы.
 * По умолчанию выключено, чтобы не пугать пользователя внезапной озвучкой.
 */
fun autoReadAutoStart() = preferenceStore.getBoolean("pref_autoread_auto_start", false)

/**
 * Запомненная нормализованная область сканирования (0..1 box) для
 * автопрокрутки: задаётся длительным касанием (autoclick с удержанием)
 * и переиспользуется, чтобы не выбирать область заново на каждом кадре.
 * Формат "left,top,right,bottom"; пустая строка = не задана.
 */
fun rememberedScanRegion() = preferenceStore.getString("pref_autoread_remembered_region", "")

// AI-определение пола говорящего (Gemini Vision по лицам и баллонам):
// женские реплики читает женский голос-пресет, мужские — мужской.
// Требует Google AI ключ; выключено по умолчанию (онлайн, медленнее).
fun aiGenderVoices() = preferenceStore.getBoolean("pref_ai_gender_voices", false)

// Целевой язык перевода перед озвучкой. Раньше был жёстко "ru" в коде
// AutoReadEngine, из-за чего англоязычный пользователь получал русскую
// озвучку независимо от настроек.
fun translateTarget() = preferenceStore.getString("pref_translate_target", "ru")

// ---- Офлайн-распознавание (Tesseract, модели в APK) ----
// Языки распознавания: eng+rus | rus | eng (оба .traineddata лежат в APK)
fun tessLangs() = preferenceStore.getString("pref_tess_langs", "eng+rus")

// Режим сегментации страницы Tesseract:
// single_block (баллон целиком, дефолт) | auto | sparse | single_line
fun tessPsm() = preferenceStore.getString("pref_tess_psm", "single_block")

// Апскейл мелких кропов: минимальная короткая сторона в px (0 = выкл).
// Tesseract резко лучше читает текст, когда буквы >= ~20px.
fun tessUpscaleMinSide() = preferenceStore.getInt("pref_tess_upscale", 320)

// Предобработка перед распознаванием: ч/б + усиление контраста
fun tessPreprocess() = preferenceStore.getBoolean("pref_tess_preprocess", true)

// Держать офлайн-модели распакованными между сессиями:
// быстрее старт движка, но ~8МБ постоянно на диске (иначе — только
// tar.xz внутри APK, извлечение при каждом первом использовании).
fun keepOfflinePacks() = preferenceStore.getBoolean("pref_keep_offline_packs", false)

// ---- Онлайн AI-ассистент (пол говорящих, помощь читалке) ----
// Провайдер: zen (без ключа) | openrouter (нужен ключ)
fun aiProvider() = preferenceStore.getString("pref_ai_provider", "zen")

// Вкладка «AI» в нижней навигации: показать/скрыть. Агент при скрытой
// вкладке остаётся доступен из внешнего браузера (порт 8765), если
// включён встроенный сервер.
fun aiTabVisible() = preferenceStore.getBoolean("pref_ai_tab_visible", false)

// Встроенный HTTP-сервер агента (http://127.0.0.1:8765 и по Wi-Fi)
fun aiHttpServer() = preferenceStore.getBoolean("pref_ai_http_server", false)

/** Секрет доступа к встроенному HTTP-серверу AI (генерируется лениво при старте). */
fun aiHttpToken() = preferenceStore.getString("pref_ai_http_token", "")

// GitHub PAT для полу-онлайн LLM-сессий (llm-runner.yml): нужен scope
// actions:write на репозиторий. Хранится только на устройстве.
fun githubPat() = preferenceStore.getString("pref_github_pat", "")

// Бэкенд AI-чата: online (Zen/OpenRouter) | local (LLM на телефоне) |
// runner (полу-онлайн, GitHub-ранер)
fun aiBackend() = preferenceStore.getString("pref_ai_backend", "online")

// ---- Раздельный выбор моделей: OCR / чат / оркестратор ----
// Оркестратор — агент читалки (вызывает инструменты, выводит правила
// книги). Пустое значение = «как у чата», поэтому у тех, кто ничего не
// выбирал, поведение не меняется; см. AiModelRoles.
fun aiOrchestratorBackend() = preferenceStore.getString("pref_ai_orchestrator_backend", "")

/** Модель оркестратора ("" = модель чата). Для Zen берётся из каталога. */
fun aiOrchestratorModel() = preferenceStore.getString("pref_ai_orchestrator_model", "")

fun aiBookLookup() = preferenceStore.getString("pref_ai_book_lookup", "on")

// Выбранная локальная модель (id из LocalLlm.CATALOG)
fun localLlmModel() = preferenceStore.getString("pref_local_llm_model", "")

// ONNX-голос по умолчанию (id из OnnxTts.CATALOG)
/** Адрес локального TTS-сервера (tools/remote_tts_server.py на ПК/ранере). */
fun remoteTtsUrl() = preferenceStore.getString("pref_remote_tts_url", "")

// Пакет системного TTS-движка: "" = движок по умолчанию системы.
// Примеры: com.google.android.tts, com.github.olga_yakovleva.rhvoice.android,
// com.acapelagroup.android.tts — любой установленный на устройстве.
fun systemTtsEngine() = preferenceStore.getString("pref_system_tts_engine", "")

// Разрешение агенту (любой модели) пользоваться ранером: запускать
// сессии и говорить с моделью на нём. Выключено по умолчанию —
// включается в настройках вкладки AI (⚙), как просил пользователь
// («с уточнением с настроек»).
fun aiAllowRunner() = preferenceStore.getBoolean("pref_ai_allow_runner", false)

// Разрешение агенту обращаться к GitHub API привязанным PAT-токеном
// (список воркфлоу, статусы, диспатч). Тоже opt-in.
fun aiAllowGithub() = preferenceStore.getBoolean("pref_ai_allow_github", false)

// Модель Zen (opencode.ai/zen, бесплатные *-free, работают без ключа)
fun zenModel() = preferenceStore.getString("pref_zen_model", "mimo-v2.5-free")

// Автосмена моделей: при лимите/ошибке выбранной модели запрос уходит
// следующей из списка. Выключено — только выбранная модель.
fun aiAutoRotate() = preferenceStore.getBoolean("pref_ai_auto_rotate", true)

// Показывать «размышления» reasoning-моделей в AI-чате (блок 🤔 под ответом)
fun aiShowReasoning() = preferenceStore.getBoolean("pref_ai_show_reasoning", false)

// Бесплатная модель OpenRouter (суффикс :free)
fun openrouterFreeModel() = preferenceStore.getString("pref_openrouter_free_model", "")

// ---- Вид подсветки реплики ----
// Цвет рамки/подчёркивания текущей реплики (ARGB). По умолчанию — бирюзовый,
// как на скриншотах пользователя.
fun highlightColor() = preferenceStore.getLong("pref_highlight_color", 0xFF00E5FFL)

// Стиль: bubble (мягкое пятно, по умолчанию) | box (рамка) |
// underline (подчёркивание) | both
// По умолчанию — видимая рамка: «bubble» (еле заметные круги) пользователь
// воспринял как отсутствие подсветки вообще.
fun highlightStyle() = preferenceStore.getString("pref_highlight_style", "box")

// Толщина рамки/линии в dp
fun highlightWidth() = preferenceStore.getFloat("pref_highlight_width", 3f)

// Показывать номера реплик на странице (порядок чтения). Номера видны
// глазами, но TTS их не произносит — см. SpeechMarkup.
fun showSpeechNumbers() = preferenceStore.getBoolean("pref_show_speech_numbers", true)

// Разные голоса разным персонажам одного пола в сцене
fun perSpeakerVoices() = preferenceStore.getBoolean("pref_per_speaker_voices", true)

// ---- Выбор голоса в читалке ----
// false — пол реплики определяется автоматически (морфология → словарь →
// AI Vision). true — читатель сам выбрал голос кнопкой в читалке, и он
// применяется ко всем репликам.
fun manualVoiceMode() = preferenceStore.getBoolean("pref_manual_voice_mode", false)

// Какой голос использовать в ручном режиме: "female" | "male"
fun manualVoiceGender() = preferenceStore.getString("pref_manual_voice_gender", "female")

// ---- Продвинутые настройки голоса (запрос: 1/2/3 голоса, муж/жен/нарратор) ----
/** Режим озвучки: single (один голос нарратора) | dual (муж+жен) | triple (муж+жен+нарратор) */
fun voiceMode() = preferenceStore.getString("pref_voice_mode", "dual")

/** Пол нарратора в режиме single/triple: male | female | auto */
fun narratorGender() = preferenceStore.getString("pref_voice_narrator_gender", "female")

/** Движок для мужского голоса: system_tts | google_web | remote_tts | eleven_api */
fun voiceMaleEngine() = preferenceStore.getString("pref_voice_male_engine", "system_tts")

/** Движок для женского голоса */
fun voiceFemaleEngine() = preferenceStore.getString("pref_voice_female_engine", "system_tts")

/** Движок для голоса нарратора */
fun voiceNarratorEngine() = preferenceStore.getString("pref_voice_narrator_engine", "system_tts")

// ---- Оверлей и уведомления ----
/** Компактный оверлей (уменьшенный) вместо полноэкранного затемнения */
fun ocrOverlayCompact() = preferenceStore.getBoolean("pref_ocr_overlay_compact", true)

/**
 * Рисовать распознанный текст поверх страницы в читалке.
 *
 * Выключено = оверлей не рисуется вовсе: на светлых страницах (бумага,
 * скан с белым фоном) белый текст поверх картинки был не виден, а
 * выключить его было нечем — кроме как уйти в настройки шапки, где такой
 * пункт не было.
 */
fun ocrPageTextOverlay() = preferenceStore.getBoolean("pref_ocr_page_text_overlay", true)

/** Дублировать распознанный текст в шторку уведомлений */
fun ocrToNotification() = preferenceStore.getBoolean("pref_ocr_to_notification", false)

/** Стриминг подсветки: подсвечивать слово сразу по мере распознавания */
fun ocrStreamingHighlight() = preferenceStore.getBoolean("pref_ocr_streaming_highlight", true)

// ---- Формы области сканирования ----
/** Форма рамки сканирования: rect | circle | diamond | hexagon | octagon | figure8 | free */
fun scanShape() = preferenceStore.getString("pref_scan_shape", "rect")

// ---- Авточтение: скорость автолистания вебтуна ----
/**
 * Скорость автолистания в авточтении вебтуна:
 *  - phrase — плавно ПОФРАЗНО: прочитал реплику — прокрутил ровно на её
 *    высоту, внизу уже следующая (нет перечитывания границ кадров);
 *  - slow — медленно (~15% экрана за шаг);
 *  - normal — обычно (~35% экрана за шаг, с перекрытием кадра);
 *  - fast — быстрее (~55%);
 *  - max — максимально (~80%).
 */
fun autoReadWebtoonSpeed() = preferenceStore.getString("pref_autoread_webtoon_speed", "normal")

// ---- Веб: сохранение как локальная глава ----
/** Сохранять веб-страницы как локальные главы с изоляцией по сайту */
fun webSavePerSiteFolder() = preferenceStore.getBoolean("pref_web_per_site_folder", true)

// ---- История сканирования (персистент) ----
/** Хранить историю сканирования между перезапусками */
fun persistOcrHistory() = preferenceStore.getBoolean("pref_persist_ocr_history", true)

// ---- AI-чат продвинутый ----
/** Лимит истории чата (сообщений) — чтобы не тратить 50к токенов */
fun aiHistoryLimit() = preferenceStore.getInt("pref_ai_history_limit", 12)

/** Лимит токенов на один ответ (reasoning + content) */
fun aiTokenBudget() = preferenceStore.getInt("pref_ai_token_budget", 4000)

/** Показывать что доступно/невозможно (availability report) */
fun aiShowAvailability() = preferenceStore.getBoolean("pref_ai_show_availability", true)

// Local Model Management (модели НЕ входят в APK — по умолчанию не установлены,
// из коробки работают только онлайн-движки)
fun isMangaOcrDownloaded() = preferenceStore.getBoolean("pref_model_manga_ocr_downloaded", false)
fun isFastOcrDownloaded() = preferenceStore.getBoolean("pref_model_fast_ocr_downloaded", false)
fun isPanelDetectorDownloaded() = preferenceStore.getBoolean("pref_model_panel_detector_downloaded", false)

// ---- STT для игр (речь → текст → русские голоса, реал-тайм) ----
/** Слушать микрофон и гнать речь в текст (системный SpeechRecognizer). */
fun sttEnabled() = preferenceStore.getBoolean("pref_stt_enabled", false)

/** Язык речи в игре (BCP-47): игры обычно английские. */
fun sttSourceLang() = preferenceStore.getString("pref_stt_source_lang", "en-US")

/** Переводить распознанное в русский перед озвучкой. */
fun sttTranslate() = preferenceStore.getBoolean("pref_stt_translate", true)

/** Пол голоса для игровых реплик: auto/female/male/narrator. */
fun gameVoiceGender() = preferenceStore.getString("pref_game_voice_gender", "auto")

