package eu.kanade.tachiyomi.data.ai

import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import kotlinx.coroutines.withTimeoutOrNull
import org.json.JSONObject

object ReaderAiActions {

    private const val TIMEOUT_MS = 120_000L

    private val actions = LinkedHashMap<String, suspend (JSONObject) -> String>()

    fun register(id: String, block: suspend (JSONObject) -> String) {
        synchronized(actions) { actions[id] = block }
    }

    fun unregister(id: String) {
        synchronized(actions) { actions.remove(id) }
    }

    fun unregisterAll(prefix: String) {
        synchronized(actions) {
            actions.keys.filter { it.startsWith(prefix) }.forEach { actions.remove(it) }
        }
    }

    fun ids(): List<String> = synchronized(actions) { actions.keys.toList() }

    fun describe(): String {
        val list = ids().map { it.removePrefix("reader.") }
        return if (list.isEmpty()) {
            "Читалка не зарегистрировала действия (открой книгу в читалке)."
        } else {
            "Доступные действия читалки: " + list.joinToString(", ")
        }
    }

    suspend fun run(id: String, args: JSONObject): String = withContext(Dispatchers.IO) {
        val block = synchronized(actions) { actions[id] ?: actions["reader.$id"] }
        if (block == null) {
            return@withContext "ОШИБКА: действия «$id» нет. ${describe()}"
        }
        val result = withTimeoutOrNull(TIMEOUT_MS) { runCatching { block(args) } }
        when {
            result == null -> "ДЕЙСТВИЕ «$id» не ответило за ${TIMEOUT_MS / 1000}с"
            result.isFailure -> "ОШИБКА действия «$id»: ${result.exceptionOrNull()?.message?.take(160)}"
            else -> result.getOrDefault("").ifBlank { "ДЕЙСТВИЕ «$id»: пустой результат" }
        }
    }
}

package eu.kanade.tachiyomi.data.ai

import android.content.Context
import android.graphics.Bitmap
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import mihon.data.ocr.ContentAutoPreset
import mihon.data.ocr.OcrContentType
import mihon.data.ocr.OcrRegionRules
import mihon.data.ocr.OcrTuning
import mihon.domain.ocr.service.OcrPreferences
import uy.kohesive.injekt.Injekt
import uy.kohesive.injekt.api.get
import java.io.File

object ReaderBookLookup {

    private const val FRAME_MAX_EDGE = 1400
    private const val OCR_TEXT_LIMIT = 900

    data class Frame(
        val width: Int,
        val height: Int,
        val rtl: Boolean,
        val webtoon: Boolean,
        val vertical: Boolean,
    )

    data class Verdict(
        val type: OcrContentType,
        val readingOrder: String,
    )

    suspend fun inspect(
        context: Context,
        mangaId: Long,
        mangaTitle: String,
        chapterName: String?,
        bitmap: Bitmap?,
    ): String? = withContext(Dispatchers.IO) {
        val prefs = runCatching { Injekt.get<OcrPreferences>() }.getOrNull() ?: return@withContext null
        if (prefs.aiBookLookup().get() == "off") return@withContext null
        val book = BookKnowledge.load(context, mangaId)
        if (book.title.isBlank() && mangaTitle.isNotBlank()) book.title = mangaTitle
        if (book.researched) return@withContext null

        val frame = frameOf(bitmap)
        val ocrText = bitmap?.let { ocrOf(context, it) }.orEmpty()
        val verdict = classify(context, prefs, mangaTitle, frame, ocrText)
        if (verdict != null) {
            applyVerdict(prefs, mangaId, verdict)
            book.contentType = verdict.type.id
            book.readingOrder = verdict.readingOrder
            BookKnowledge.save(context, book)
        }

        val researched = research(context, prefs, mangaId, mangaTitle, chapterName, book)
        if (researched != null) {
            BookKnowledge.render(context, mangaId)
        } else {
            verdict?.let {
                "Тип: ${it.type.title}, порядок: ${OcrRegionRules.orderTitle(it.readingOrder)}. " +
                    "Интернет недоступен — детали не проверены."
            }
        }
    }

    private fun frameOf(bitmap: Bitmap?): Frame? {
        val ctx = mihon.data.ocr.ReaderContextBus.current.value
        if (bitmap == null || bitmap.width <= 0 || bitmap.height <= 0) return null
        val ratio = bitmap.height.toFloat() / bitmap.width
        return Frame(
            width = bitmap.width,
            height = bitmap.height,
            rtl = ctx?.rtl ?: false,
            webtoon = ctx?.webtoon ?: (ratio >= 1.8f),
            vertical = ctx?.vertical ?: (ratio >= 1.8f),
        )
    }

    private suspend fun ocrOf(context: Context, bitmap: Bitmap): String {
        val file = File(context.cacheDir, "ai_probe_frame.jpg")
        val saved = runCatching {
            val scaled = if (maxOf(bitmap.width, bitmap.height) > FRAME_MAX_EDGE) {
                val scale = FRAME_MAX_EDGE.toFloat() / maxOf(bitmap.width, bitmap.height)
                Bitmap.createScaledBitmap(
                    bitmap,
                    (bitmap.width * scale).toInt().coerceAtLeast(1),
                    (bitmap.height * scale).toInt().coerceAtLeast(1),
                    true,
                )
            } else {
                bitmap
            }
            file.outputStream().use { out ->
                scaled.compress(Bitmap.CompressFormat.JPEG, 80, out)
            }
            if (scaled !== bitmap && !scaled.isRecycled) scaled.recycle()
            true
        }.getOrDefault(false)
        if (!saved) return ""
        return AiAgent.ocrAttachment(file).orEmpty().take(OCR_TEXT_LIMIT)
    }

    private suspend fun classify(
        context: Context,
        prefs: OcrPreferences,
        title: String,
        frame: Frame?,
        ocrText: String,
    ): Verdict? {
        val resolution = AiBackends.resolve(context, prefs.aiBackend().get())
        val chat = resolution.chat ?: return null
        val geometry = if (frame == null) {
            "кадр недоступен"
        } else {
            "размер кадра ${frame.width}x${frame.height}, " +
                "соотношение %.2f, ".format(frame.height.toFloat() / frame.width) +
                "обложка/страница читается справа налево=${frame.rtl}, " +
                "вертикальная=${frame.vertical}, вебтун=${frame.webtoon}"
        }
        val prompt = buildString {
            append("Определи тип контента и направление чтения по кадру страницы.\n")
            append("ТИП: manga (японская манга), manhwa (корейский веб-комикс), ")
            append("manhua (китайские вертикальные колонки), comic (западный комикс) или UNKNOWN.\n")
            append("ПОРЯДОК ЧТЕНИЯ: rtl (справа налево), ltr (слева направо) или vertical (сверху вниз).\n")
            append("Важно: направление определяй по самому кадру — пузы и панели могут идти ")
            append("и справа налево, и слева направо, не суди только по типу.\n")
            if (title.isNotBlank()) append("Название: $title\n")
            append("Геометрия: $geometry\n")
            if (ocrText.isNotBlank()) append("Распознанный текст кадра: ").append(ocrText.take(400)).append('\n')
            append("Ответь ДВУМЯ строками без пояснений: первая — тип, вторая — порядок чтения.")
        }
        val reply = runCatching {
            chat(
                prompt,
                "Ты классификатор страниц в manga-читалке. Определяешь тип контента и направление чтения. Отвечай двумя строками.",
            )
        }.getOrNull() ?: return null
        val text = reply?.content.orEmpty().uppercase()
        val type = when {
            text.contains("MANHWA") -> OcrContentType.MANHWA
            text.contains("MANHUA") -> OcrContentType.MANHUA
            text.contains("COMIC") -> OcrContentType.COMIC
            text.contains("MANGA") -> OcrContentType.MANGA
            else -> return null
        }
        val order = when {
            text.contains("VERTICAL") -> "vertical"
            text.contains("LTR") -> "ltr"
            text.contains("RTL") -> "rtl"
            else -> OcrTuning.preset(type).readingOrder
        }
        return Verdict(type = type, readingOrder = order)
    }

    private fun applyVerdict(prefs: OcrPreferences, mangaId: Long, verdict: Verdict) {
        val type = verdict.type
        if (type == OcrContentType.BALANCED) return
        val current = prefs.contentType().get()
        if (current != "balanced" && current != type.id) return
        prefs.contentType().set(type.id)
        prefs.scanReadingOrder().set(verdict.readingOrder)
        ContentAutoPreset.rememberManual(mangaId, type.id, prefs)
    }

    private suspend fun research(
        context: Context,
        prefs: OcrPreferences,
        mangaId: Long,
        title: String,
        chapterName: String?,
        book: BookKnowledge.Book,
    ): String? {
        val resolution = AiBackends.resolve(context, prefs.aiBackend().get())
        val chat = resolution.chat ?: return null
        val task = buildString {
            append("Изучи книгу и сохрани знание о ней.\n")
            if (title.isNotBlank()) append("Название: $title\n")
            if (!chapterName.isNullOrBlank()) append("Открыта глава: $chapterName\n")
            if (book.contentType.isNotBlank()) append("Тип контента: ").append(book.contentType).append('\n')
            append("Сделай по порядку:\n")
            append("1) web_search — найди, где эту книгу читают, и официальную страницу.\n")
            append("2) web_fetch — открой найденную страницу и возьми оттуда факты.\n")
            append("3) book_remember kind=site — куда читать (ссылка).\n")
            append("4) book_remember kind=summary — о чём книга, 1-2 предложения.\n")
            append("5) book_remember kind=fact — 2-4 факта: издание, автор, жанр, по чему читать.\n")
            append("Если интернет недоступен — скажи об этом прямо и не выдумывай ссылки.\n")
            append("Ответ пользователю — 2-3 предложения.")
        }
        val reply = AiAgent.run(
            context = context,
            userText = task,
            history = emptyList(),
            chatFn = chat,
            mangaId = mangaId,
            bookContext = BookKnowledge.render(context, mangaId).ifBlank { null },
        )
        return reply.text.takeIf { it.isNotBlank() }
    }
}

package eu.kanade.tachiyomi.data.ai

import java.io.File

/**
 * Обзор workspace: что вообще лежит в папке и как это прочитать целиком.
 *
 * Читатель просил, чтобы агент «видел сразу всё, что в воркспейсе, анализировал
 * по очереди и задавал уточняющие вопросы». Раньше у агента был только
 * `read_file` по одному файлу: чтобы понять, что есть, нужно было угадать имя
 * и проверить всё подряд, а на несуществующем файле он получал «Файл не
 * найден» и строил выводы по неполной картине.
 *
 * Здесь две чистые функции (без `Context`, с `File` вместо него) — их можно
 * проверить обычными unit-тестами на JVM, и в них же живёт главное: **бюджет
 * символов**. Список из сотни файлов, выведенный в ответ целиком, съедает
 * контекст хода, после которого модель начинает отвечать мусором, поэтому
 * список обрезается по лимиту и честно говорит, что не показал.
 */
object AiWorkspaceSurvey {

    /** Сколько символов отдаём под один обзор по умолчанию. */
    const val DEFAULT_TREE_BUDGET = 6_000

    /** Сколько символов текста читать за один пакетный вызов. */
    const val DEFAULT_READ_BUDGET = 12_000

    /**
     * Дерево файлов: папки и файлы с размерами, от самых свежих.
     *
     * @param subdir подкаталог относительно корня, "" или "." — весь корень.
     * @param limit максимум строк, даже если символы ещё остались.
     * @param maxBudget обрезка по символам.
     */
    fun renderTree(root: File, subdir: String = "", limit: Int = 200, maxBudget: Int = DEFAULT_TREE_BUDGET): String {
        val base = resolveDir(root, subdir) ?: return "Каталог не найден: $subdir"
        val entries = base.walkTopDown()
            .onEnter { it.canRead() }
            .filter { it != base }
            .sortedWith(
                compareBy(
                    { it.path.count { ch -> ch == '/' || ch == java.io.File.separatorChar } },
                    { it.name.lowercase() },
                ),
            )
            .toList()

        if (entries.isEmpty()) return "В каталоге ${describe(root, base)} пусто"

        val sb = StringBuilder("В папке ${describe(root, base)} — ${entries.size} объект(ов):\n")
        var shown = 0
        var truncated = false
        // Место под завершающую пометку резервируем заранее, иначе она сама
        // вылезет за бюджет: бюджет — это предел ответа модели, а не «список
        // плюс ещё немножка».
        val reserve = 70 + entries.size.toString().length
        for (f in entries) {
            if (shown >= limit) {
                truncated = true
                break
            }
            val rel = relative(root, f)
            val line = buildString {
                append("  ")
                append(rel)
                if (f.isDirectory) {
                    append('/')
                } else {
                    append(" — ")
                    append(f.length() / 1024)
                    append(" КБ")
                }
            }
            // Обрезаем по символам, но не посреди строки: недописанный путь
            // хуже, чем лишняя строка в ответе.
            if (sb.length + line.length + 1 + reserve > maxBudget) {
                truncated = true
                break
            }
            sb.append(line).append('\n')
            shown++
        }
        if (truncated) {
            sb.append("… показано $shown из ${entries.size}. Смотри по частям: workspace_list с path.")
        }
        return sb.toString().trimEnd()
    }

    /**
     * Чтение нескольких файлов по очереди в пределах бюджета символов.
     *
     * Порядок сохраняется: для книги «глава 1 → глава 2» это важно, а сортировка
     * по имени переставляла бы их произвольно. Файл, который не влез в бюджет,
     * помечается, а не молча пропускается — иначе агент решит, что прочитал всё.
     */
    fun readMany(root: File, names: List<String>, budget: Int = DEFAULT_READ_BUDGET): String {
        if (names.isEmpty()) return "Не указано ни одного файла"
        val sb = StringBuilder()
        var spent = 0
        for (name in names) {
            val f = resolveFile(root, name)
            if (f == null || !f.isFile) {
                sb.append("— $name: НЕ НАЙДЕН\n")
                continue
            }
            if (f.extension.lowercase() in IMAGE_EXT) {
                // Раньше здесь было «я не вижу картинки». Это неправда: и
                // read_file, и see_image спрашивают vision-модель. Одно
                // сообщение говорило «не вижу», другое — «спрошу», и модель
                // верила тому, что прочитала последним.
                sb.append("— $name: изображение ${f.length() / 1024} КБ; текста нет. ")
                sb.append("Спросить vision можно see_image {\"name\":\"$name\",\"question\":\"что на ней\"}, ")
                sb.append("прочитать — read_file\n")
                continue
            }
            val text = runCatching { f.readText() }.getOrElse {
                sb.append("— $name: НЕ ЧИТАЕТСЯ\n")
                continue
            }
            val header = "— $name (${text.length} симв.)\n"
            val room = budget - spent - header.length
            if (room <= 0) {
                sb.append("— $name: не вошёл в бюджет чтения, читай отдельно read_file\n")
                continue
            }
            val body = if (text.length > room) text.take(room) + "\n… (файл обрезан по бюджету)" else text
            sb.append(header).append(body).append('\n')
            spent += header.length + body.length
            if (spent >= budget) {
                val rest = names.drop(names.indexOf(name) + 1)
                if (rest.isNotEmpty()) {
                    sb.append("Бюджет чтения исчерпан, не прочитано: ${rest.joinToString(", ")}")
                }
                break
            }
        }
        return sb.toString().trimEnd()
    }

    private val IMAGE_EXT = setOf("png", "jpg", "jpeg", "webp", "gif", "bmp")

    private fun resolveDir(root: File, subdir: String): File? {
        val clean = subdir.trim().trimStart('/')
        if (clean.isEmpty() || clean == ".") return root
        val f = File(root, clean)
        return f.takeIf { it.isDirectory }
    }

    private fun resolveFile(root: File, name: String): File? {
        val clean = name.trim().trimStart('/')
        if (clean.isEmpty()) return null
        val f = File(root, clean)
        // Выход за пределы workspace запрещён: путь из модели не должен
        // приводить к файлам приложения.
        return runCatching {
            if (f.canonicalPath.startsWith(root.canonicalPath)) f else null
        }.getOrNull()
    }

    private fun relative(root: File, f: File): String = runCatching {
        f.absolutePath.removePrefix(root.absolutePath).trimStart('/')
    }.getOrDefault(f.name)

    private fun describe(root: File, dir: File): String =
        if (dir == root) "workspace (корень)" else relative(root, dir)
}

