                                    val uri = viewModel.getCurrentPageUri()
                                    dictionarySearchScreenModel.addGroupToAnki(terms, uri)
                                }
                            }
                        },
                        onPlayAudioClick = dictionarySearchScreenModel::fetchAndPlayAudio,
                        onSpeak = {
                            eu.kanade.tachiyomi.data.tts.TtsSpeaker.speak(
                                this@ReaderActivity,
                                dialog.queryText,
                            )
                        },
                        onSpeakRole = { role ->
